import React from "react";
import { renderLatestData,initAnedyaClient } from "yt-tutorial-app";

function App() {
  const tokenId = "pvvYKc5CJW4d32cnIEECrSU";
  const token =
    "TXtad1e9J2LP4MimuWqAI8pDvqj02RKbt1uuhvFn0xWP1HHxp4cOWFOStyZa8oDk";
  const nodeId = "01979c1d-4fba-7424-b186-f89caeb7fb8f";

  const { anedya, client } = initAnedyaClient(tokenId, token);

  const { WidgetComponent } = renderLatestData(
    client,
    anedya,
    nodeId,
    "temperature",
    0,
    "#ffeaea",
    "red",
    "18px"
  );


  return (
    <div style={{ padding: "2rem" }}>
      <h1>Test Widget SDK</h1>
      {WidgetComponent}
      {/* 
      <LatestDataWidget
        client={clientInstance.client}
        anedya={anedya}
        nodeId={nodeId}
        variable="temperature"
        refreshInterval={5000}
        backgroundColor="#ffeaea"
        textColor="red"
        fontSize="18px"
      /> */}
    </div>
  );
}

export default App;
